-- NEXORA FORGE ACADEMY INSTALL — PART 20/21
-- Curriculum lessons 307-324 of 324

begin;
insert into public.academy_lessons(id,course_id,title,slug,summary,content_html,starter_code,exercise,status,sort_order,estimated_minutes)
select x.id,c.id,x.title,x.slug,x.summary,x.content_html,x.starter_code,x.exercise,x.status,x.sort_order,x.estimated_minutes
from jsonb_to_recordset($lessons$[{"id":"curriculum-324-javascript-advanced-19","course_id":"javascript-advanced","title":"MutationObserver برای DOM","slug":"javascript-advanced-19","summary":"MutationObserver تغییرات ساختار و ویژگی DOM را بدون polling گزارش می‌کند.","content_html":"<h3>هدف درس</h3><p>تغییرات DOM را مشاهده کن.</p><h3>نمونه و بررسی</h3><p>فقط mutationهای موردنیاز را فعال کن.</p><pre><code>const node=document.querySelector('#list'); const observer=new MutationObserver(records=&gt;console.log(records.length)); if(node) observer.observe(node,{childList:true,subtree:true});</code></pre><h3>تمرین عملی</h3><p>افزوده شدن کارت جدید را تشخیص بده و observer را disconnect کن.</p><h3>نکته فنی</h3><p>callback به‌صورت ناهمگام اجرا می‌شود.</p><h3>معیار موفقیت</h3><p>تغییر تشخیص داده و observer پاک‌سازی شود.</p>","starter_code":"const node=document.querySelector('#list'); const observer=new MutationObserver(records=>console.log(records.length)); if(node) observer.observe(node,{childList:true,subtree:true});","exercise":"افزوده شدن کارت جدید را تشخیص بده و observer را disconnect کن.","status":"published","sort_order":19,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-20","course_id":"javascript-advanced","title":"IntersectionObserver و بارگذاری تنبل","slug":"javascript-advanced-20","summary":"IntersectionObserver ورود عنصر به viewport را تشخیص می‌دهد و برای lazy loading مفید است.","content_html":"<h3>هدف درس</h3><p>ورود عنصر به محدوده دید را تشخیص بده.</p><h3>نمونه و بررسی</h3><p>پس از بارگذاری unobserve کن.</p><pre><code>const observer=new IntersectionObserver(entries=&gt;entries.forEach(e=&gt;{if(e.isIntersecting){console.log(e.target.id);observer.unobserve(e.target)}}),{rootMargin:'100px'}); document.querySelectorAll('[data-watch]').forEach(x=&gt;observer.observe(x));</code></pre><h3>تمرین عملی</h3><p>تصاویر درس را نزدیک viewport بارگذاری کن.</p><h3>نکته فنی</h3><p>این API جایگزین اندازه‌گیری دقیق پیکسلی نیست.</p><h3>معیار موفقیت</h3><p>هر تصویر فقط یک بار بارگذاری شود.</p>","starter_code":"const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){console.log(e.target.id);observer.unobserve(e.target)}}),{rootMargin:'100px'}); document.querySelectorAll('[data-watch]').forEach(x=>observer.observe(x));","exercise":"تصاویر درس را نزدیک viewport بارگذاری کن.","status":"published","sort_order":20,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-21","course_id":"javascript-advanced","title":"ResizeObserver و اندازه کامپوننت","slug":"javascript-advanced-21","summary":"ResizeObserver تغییر اندازه عنصر را مستقل از اندازه پنجره گزارش می‌کند.","content_html":"<h3>هدف درس</h3><p>اندازه خود عنصر را مشاهده کن.</p><h3>نمونه و بررسی</h3><p>تغییر layout در callback را کنترل کن.</p><pre><code>const panel=document.querySelector('#panel'); const ro=new ResizeObserver(entries=&gt;console.log(entries[0].contentRect.width)); if(panel) ro.observe(panel);</code></pre><h3>تمرین عملی</h3><p>کارت آمار را با عرض container به حالت فشرده یا گسترده ببر.</p><h3>نکته فنی</h3><p>ممکن است حلقه resize ایجاد شود.</p><h3>معیار موفقیت</h3><p>تغییر breakpoint داخلی بدون loop تشخیص داده شود.</p>","starter_code":"const panel=document.querySelector('#panel'); const ro=new ResizeObserver(entries=>console.log(entries[0].contentRect.width)); if(panel) ro.observe(panel);","exercise":"کارت آمار را با عرض container به حالت فشرده یا گسترده ببر.","status":"published","sort_order":21,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-22","course_id":"javascript-advanced","title":"CustomEvent برای ارتباط اجزا","slug":"javascript-advanced-22","summary":"CustomEvent payload را در detail حمل می‌کند و وابستگی مستقیم کامپوننت‌ها را کم می‌کند.","content_html":"<h3>هدف درس</h3><p>ارتباط event-driven بساز.</p><h3>نمونه و بررسی</h3><p>نام رویداد و schema داده را مستند کن.</p><pre><code>document.addEventListener(\"course:completed\", event =&gt; {\n  console.log(\"progress update:\", event.detail);\n});\nconst completion = new CustomEvent(\"course:completed\", {\n  detail: {id: \"js-36\", score: 95}\n});\ndocument.dispatchEvent(completion);</code></pre><h3>تمرین عملی</h3><p>رویداد تکمیل درس را منتشر و در نوار پیشرفت دریافت کن.</p><h3>نکته فنی</h3><p>ابتدا شنونده ثبت می‌شود و بعد رویداد منتشر می‌شود؛ dispatch پیش از ثبت listener باعث از دست رفتن همان رویداد می‌شود.</p><h3>معیار موفقیت</h3><p>ناشر و شنونده مستقل و هماهنگ کار کنند.</p>","starter_code":"document.addEventListener(\"course:completed\", event => {\n  console.log(\"progress update:\", event.detail);\n});\nconst completion = new CustomEvent(\"course:completed\", {\n  detail: {id: \"js-36\", score: 95}\n});\ndocument.dispatchEvent(completion);","exercise":"رویداد تکمیل درس را منتشر و در نوار پیشرفت دریافت کن.","status":"published","sort_order":22,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-23","course_id":"javascript-advanced","title":"BroadcastChannel بین زبانه‌ها","slug":"javascript-advanced-23","summary":"BroadcastChannel پیام را میان contextهای هم‌مبدأ پخش می‌کند.","content_html":"<h3>هدف درس</h3><p>پیام بین زبانه‌ها ردوبدل کن.</p><h3>نمونه و بررسی</h3><p>payload را اعتبارسنجی و channel را ببند.</p><pre><code>const channel=new BroadcastChannel('academy'); channel.postMessage({type:'theme',value:'dark'}); channel.onmessage=e=&gt;console.log(e.data);</code></pre><h3>تمرین عملی</h3><p>تغییر تم را بین دو زبانه هم‌مبدأ همگام کن.</p><h3>نکته فنی</h3><p>فقط same-origin را پشتیبانی می‌کند.</p><h3>معیار موفقیت</h3><p>زبانه دیگر پیام را بگیرد و کانال cleanup شود.</p>","starter_code":"const channel=new BroadcastChannel('academy'); channel.postMessage({type:'theme',value:'dark'}); channel.onmessage=e=>console.log(e.data);","exercise":"تغییر تم را بین دو زبانه هم‌مبدأ همگام کن.","status":"published","sort_order":23,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-24","course_id":"javascript-advanced","title":"WebSocket و ارتباط دوطرفه","slug":"javascript-advanced-24","summary":"WebSocket اتصال پایدار دوطرفه می‌سازد و چرخه open، message، error و close باید مدیریت شود.","content_html":"<h3>هدف درس</h3><p>چرخه عمر اتصال را مدیریت کن.</p><h3>نمونه و بررسی</h3><p>فقط در readyState برابر OPEN ارسال کن.</p><pre><code>const socket = new WebSocket(\"wss://echo.websocket.events\");\nsocket.addEventListener(\"open\", () =&gt; socket.send(\"NEXORA\"));\nsocket.addEventListener(\"message\", event =&gt; console.log(event.data));\nsocket.addEventListener(\"error\", error =&gt; console.error(\"WebSocket error:\", error));\nsocket.addEventListener(\"close\", event =&gt; console.log(\"closed:\", event.code));</code></pre><h3>تمرین عملی</h3><p>نمایشگر وضعیت زنده بساز و هنگام خروج اتصال را ببند.</p><h3>نکته فنی</h3><p>این نشانی یک سرویس echo بیرونی برای آزمایش است و ممکن است همیشه در دسترس نباشد؛ در محصول واقعی از endpoint تحت کنترل خودت استفاده کن.</p><h3>معیار موفقیت</h3><p>بازشدن، پیام و بسته‌شدن کنترل‌شده دیده شود.</p>","starter_code":"const socket = new WebSocket(\"wss://echo.websocket.events\");\nsocket.addEventListener(\"open\", () => socket.send(\"NEXORA\"));\nsocket.addEventListener(\"message\", event => console.log(event.data));\nsocket.addEventListener(\"error\", error => console.error(\"WebSocket error:\", error));\nsocket.addEventListener(\"close\", event => console.log(\"closed:\", event.code));","exercise":"نمایشگر وضعیت زنده بساز و هنگام خروج اتصال را ببند.","status":"published","sort_order":24,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-25","course_id":"javascript-advanced","title":"ReadableStream و پردازش جریانی","slug":"javascript-advanced-25","summary":"Streams API پاسخ بزرگ را chunk به chunk پردازش می‌کند.","content_html":"<h3>هدف درس</h3><p>داده را تدریجی مصرف کن.</p><h3>نمونه و بررسی</h3><p>reader را در پایان آزاد یا cancel کن.</p><pre><code>async function readReport() {\n  const response = await fetch(\"/api/report\");\n  if (!response.ok) throw new Error(`HTTP ${response.status}`);\n  if (!response.body) throw new Error(\"ReadableStream در دسترس نیست\");\n  const reader = response.body.getReader();\n  try {\n    const {value, done} = await reader.read();\n    console.log({chunkBytes: value?.length, done});\n  } finally {\n    await reader.cancel();\n  }\n}\nreadReport().catch(console.error);</code></pre><h3>تمرین عملی</h3><p>گزارش حجیم را قطعه‌ای بخوان و هنگام ترک صفحه لغو کن.</p><h3>نکته فنی</h3><p>کد نمونه یک chunk را می‌خواند و سپس reader را در finally لغو می‌کند؛ برای پردازش کامل باید تا done شدن جریان حلقه بخوانی.</p><h3>معیار موفقیت</h3><p>chunk خوانده و منابع هنگام لغو آزاد شوند.</p>","starter_code":"async function readReport() {\n  const response = await fetch(\"/api/report\");\n  if (!response.ok) throw new Error(`HTTP ${response.status}`);\n  if (!response.body) throw new Error(\"ReadableStream در دسترس نیست\");\n  const reader = response.body.getReader();\n  try {\n    const {value, done} = await reader.read();\n    console.log({chunkBytes: value?.length, done});\n  } finally {\n    await reader.cancel();\n  }\n}\nreadReport().catch(console.error);","exercise":"گزارش حجیم را قطعه‌ای بخوان و هنگام ترک صفحه لغو کن.","status":"published","sort_order":25,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-26","course_id":"javascript-advanced","title":"IndexedDB برای ذخیره ساختاریافته","slug":"javascript-advanced-26","summary":"IndexedDB پایگاه داده ناهمگام مرورگر با object store و transaction است.","content_html":"<h3>هدف درس</h3><p>داده ساختاریافته را در مرورگر ذخیره کن.</p><h3>نمونه و بررسی</h3><p>schema را در onupgradeneeded مدیریت کن.</p><pre><code>const req=indexedDB.open('AcademyDB',1); req.onupgradeneeded=()=&gt;req.result.createObjectStore('lessons',{keyPath:'id'}); req.onsuccess=()=&gt;console.log('ready'); req.onerror=()=&gt;console.error(req.error);</code></pre><h3>تمرین عملی</h3><p>store درس بساز و درج و بازیابی رکورد را با transaction پیاده کن.</p><h3>نکته فنی</h3><p>داده حساس را در IndexedDB بدون حفاظت نگذار.</p><h3>معیار موفقیت</h3><p>ساخت، درج، بازیابی و خطا مدیریت شود.</p>","starter_code":"const req=indexedDB.open('AcademyDB',1); req.onupgradeneeded=()=>req.result.createObjectStore('lessons',{keyPath:'id'}); req.onsuccess=()=>console.log('ready'); req.onerror=()=>console.error(req.error);","exercise":"store درس بساز و درج و بازیابی رکورد را با transaction پیاده کن.","status":"published","sort_order":26,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-27","course_id":"javascript-advanced","title":"Cache API و راهبرد کش","slug":"javascript-advanced-27","summary":"Cache API پاسخ‌ها را ذخیره می‌کند؛ cache key و سیاست به‌روزرسانی باید روشن باشد.","content_html":"<h3>هدف درس</h3><p>پاسخ را ذخیره و بازیابی کن.</p><h3>نمونه و بررسی</h3><p>برای داده پویا سیاست network-first یا stale-while-revalidate انتخاب کن.</p><pre><code>async function cacheDemo() {\n  const cache = await caches.open(\"nexora-v1\");\n  await cache.put(\"/demo.txt\", new Response(\"academy\"));\n  const saved = await cache.match(\"/demo.txt\");\n  console.log(await saved?.text());\n}\ncacheDemo().catch(console.error);</code></pre><h3>تمرین عملی</h3><p>فایل استاتیک نسخه‌دار را cache و cache قدیمی را پاک‌سازی کن.</p><h3>نکته فنی</h3><p>Cache API در محیط‌های امن مانند HTTPS یا localhost قابل استفاده است و برای فایل‌های پویا باید سیاست تازگی مشخص داشته باشی.</p><h3>معیار موفقیت</h3><p>نسخه جدید بدون نمایش فایل قدیمی ناخواسته ارائه شود.</p>","starter_code":"async function cacheDemo() {\n  const cache = await caches.open(\"nexora-v1\");\n  await cache.put(\"/demo.txt\", new Response(\"academy\"));\n  const saved = await cache.match(\"/demo.txt\");\n  console.log(await saved?.text());\n}\ncacheDemo().catch(console.error);","exercise":"فایل استاتیک نسخه‌دار را cache و cache قدیمی را پاک‌سازی کن.","status":"published","sort_order":27,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-28","course_id":"javascript-advanced","title":"Service Worker و چرخه عمر","slug":"javascript-advanced-28","summary":"Service Worker چرخه install، activate و fetch دارد و در secure context ثبت می‌شود.","content_html":"<h3>هدف درس</h3><p>چرخه عمر worker را پیاده کن.</p><h3>نمونه و بررسی</h3><p>scope و cache version را بررسی کن.</p><pre><code>if('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').then(r=&gt;console.log(r.scope)).catch(console.error);</code></pre><h3>تمرین عملی</h3><p>worker بساز که فایل ضروری را cache و نسخه قدیمی را حذف کند.</p><h3>نکته فنی</h3><p>در localhost و HTTPS قابل استفاده است.</p><h3>معیار موفقیت</h3><p>ثبت، فعال‌سازی و کنترل scope تست شود.</p>","starter_code":"if('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').then(r=>console.log(r.scope)).catch(console.error);","exercise":"worker بساز که فایل ضروری را cache و نسخه قدیمی را حذف کند.","status":"published","sort_order":28,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-29","course_id":"javascript-advanced","title":"Web Worker برای پردازش سنگین","slug":"javascript-advanced-29","summary":"Web Worker محاسبات را از main thread جدا می‌کند اما DOM در worker در دسترس نیست.","content_html":"<h3>هدف درس</h3><p>کار CPU را از رشته اصلی خارج کن.</p><h3>نمونه و بررسی</h3><p>پیام‌ها را ساختاریافته و خطاها را مدیریت کن.</p><pre><code>// worker.js: self.onmessage=e=&gt;self.postMessage(e.data.values.reduce((a,b)=&gt;a+b,0));\n// main.js: const w=new Worker('./worker.js'); w.postMessage({values:[1,2,3]}); w.onmessage=e=&gt;console.log(e.data);</code></pre><h3>تمرین عملی</h3><p>محاسبه حجیم را به worker بسپار و نتیجه را به رابط برگردان.</p><h3>نکته فنی</h3><p>انتقال داده معمولاً structured clone است.</p><h3>معیار موفقیت</h3><p>رابط روان بماند و نتیجه صحیح برگردد.</p>","starter_code":"// worker.js: self.onmessage=e=>self.postMessage(e.data.values.reduce((a,b)=>a+b,0));\n// main.js: const w=new Worker('./worker.js'); w.postMessage({values:[1,2,3]}); w.onmessage=e=>console.log(e.data);","exercise":"محاسبه حجیم را به worker بسپار و نتیجه را به رابط برگردان.","status":"published","sort_order":29,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-30","course_id":"javascript-advanced","title":"Performance API و اندازه‌گیری","slug":"javascript-advanced-30","summary":"Performance mark و measure زمان اجرای بخش مشخص را اندازه می‌گیرند.","content_html":"<h3>هدف درس</h3><p>گلوگاه را با اندازه‌گیری واقعی پیدا کن.</p><h3>نمونه و بررسی</h3><p>شرایط و تعداد تکرارها را ثابت نگه دار.</p><pre><code>performance.mark('start'); const data=Array.from({length:1000},(_,i)=&gt;i*2); performance.mark('end'); performance.measure('build','start','end'); console.log(performance.getEntriesByName('build').at(-1).duration);</code></pre><h3>تمرین عملی</h3><p>دو روش ساخت فهرست را در چند اجرای تکراری مقایسه کن.</p><h3>نکته فنی</h3><p>یک اجرا تحت تأثیر JIT و نویز است.</p><h3>معیار موفقیت</h3><p>نتیجه تکرارپذیر باشد و از یک نمونه نتیجه‌گیری نشود.</p>","starter_code":"performance.mark('start'); const data=Array.from({length:1000},(_,i)=>i*2); performance.mark('end'); performance.measure('build','start','end'); console.log(performance.getEntriesByName('build').at(-1).duration);","exercise":"دو روش ساخت فهرست را در چند اجرای تکراری مقایسه کن.","status":"published","sort_order":30,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-31","course_id":"javascript-advanced","title":"PerformanceObserver و پایش منابع","slug":"javascript-advanced-31","summary":"PerformanceObserver ورودی‌های عملکردی مانند resource را به‌صورت رویدادی گزارش می‌کند.","content_html":"<h3>هدف درس</h3><p>پایش عملکرد بدون polling انجام بده.</p><h3>نمونه و بررسی</h3><p>supportedEntryTypes را بررسی کن.</p><pre><code>const observer=new PerformanceObserver(list=&gt;list.getEntries().forEach(e=&gt;console.log(e.name,e.duration))); observer.observe({type:'resource',buffered:true});</code></pre><h3>تمرین عملی</h3><p>منابع کند را ثبت و بعد observer را متوقف کن.</p><h3>نکته فنی</h3><p>پشتیبانی entry type بین مرورگرها فرق دارد.</p><h3>معیار موفقیت</h3><p>گزارش ثبت و observer پاک‌سازی شود.</p>","starter_code":"const observer=new PerformanceObserver(list=>list.getEntries().forEach(e=>console.log(e.name,e.duration))); observer.observe({type:'resource',buffered:true});","exercise":"منابع کند را ثبت و بعد observer را متوقف کن.","status":"published","sort_order":31,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-32","course_id":"javascript-advanced","title":"جلوگیری از XSS در DOM","slug":"javascript-advanced-32","summary":"ورودی غیرقابل‌اعتماد اگر به‌عنوان HTML اجرا شود می‌تواند XSS ایجاد کند؛ برای متن از textContent استفاده کن.","content_html":"<h3>هدف درس</h3><p>داده را از markup اجرایی جدا نگه دار.</p><h3>نمونه و بررسی</h3><p>برای HTML ضروری از sanitizer معتبر استفاده کن.</p><pre><code>const comment='&lt;img src=x onerror=alert(1)&gt;'; document.querySelector('#comment').textContent=comment;</code></pre><h3>تمرین عملی</h3><p>نمایش نظر کاربران را ایمن کن و خطر innerHTML را با نمونه توضیح بده.</p><h3>نکته فنی</h3><p>replace ساده sanitizer کامل نیست.</p><h3>معیار موفقیت</h3><p>ورودی به‌صورت متن نمایش یابد و اجرا نشود.</p>","starter_code":"const comment='<img src=x onerror=alert(1)>'; document.querySelector('#comment').textContent=comment;","exercise":"نمایش نظر کاربران را ایمن کن و خطر innerHTML را با نمونه توضیح بده.","status":"published","sort_order":32,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-33","course_id":"javascript-advanced","title":"CSP و Trusted Types","slug":"javascript-advanced-33","summary":"CSP منابع و اسکریپت‌های مجاز را محدود می‌کند؛ Trusted Types در مرورگرهای پشتیبان sinkهای حساس را کنترل می‌کند.","content_html":"<h3>هدف درس</h3><p>سطح اجرای کد را محدود کن.</p><h3>نمونه و بررسی</h3><p>ابتدا Report-Only و سپس enforcement را آزمایش کن.</p><pre><code>// HTTP header example:\n// Content-Security-Policy: default-src 'self'; script-src 'self'; object-src 'none'; base-uri 'self'</code></pre><h3>تمرین عملی</h3><p>سیاست CSP سایت را طراحی و منابع مجاز را فهرست کن.</p><h3>نکته فنی</h3><p>CSP جایگزین اصلاح XSS نیست.</p><h3>معیار موفقیت</h3><p>منابع ضروری کار و منابع ناخواسته مسدود شوند.</p>","starter_code":"// HTTP header example:\n// Content-Security-Policy: default-src 'self'; script-src 'self'; object-src 'none'; base-uri 'self'","exercise":"سیاست CSP سایت را طراحی و منابع مجاز را فهرست کن.","status":"published","sort_order":33,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-34","course_id":"javascript-advanced","title":"Web Crypto API و digest","slug":"javascript-advanced-34","summary":"Web Crypto عملیات رمزنگاری مانند SHA-256 digest را فراهم می‌کند؛ hash ساده برای ذخیره گذرواژه مناسب نیست.","content_html":"<h3>هدف درس</h3><p>از API رمزنگاری استاندارد استفاده کن.</p><h3>نمونه و بررسی</h3><p>برای گذرواژه از Argon2id سمت سرور استفاده کن.</p><pre><code>async function createDigest() {\n  const data = new TextEncoder().encode(\"NEXORA\");\n  const hash = await crypto.subtle.digest(\"SHA-256\", data);\n  const hex = [...new Uint8Array(hash)]\n    .map(byte =&gt; byte.toString(16).padStart(2, \"0\"))\n    .join(\"\");\n  console.log(hex);\n}\ncreateDigest().catch(console.error);</code></pre><h3>تمرین عملی</h3><p>digest یک فایل آزمایشی را محاسبه و تفاوت آن را با password hashing شرح بده.</p><h3>نکته فنی</h3><p>این نمونه باید در secure context مانند HTTPS یا localhost اجرا شود؛ SHA-256 ساده برای ذخیره گذرواژه مناسب نیست.</p><h3>معیار موفقیت</h3><p>digest تکرارپذیر باشد و رمز واقعی در frontend هش/ذخیره نشود.</p>","starter_code":"async function createDigest() {\n  const data = new TextEncoder().encode(\"NEXORA\");\n  const hash = await crypto.subtle.digest(\"SHA-256\", data);\n  const hex = [...new Uint8Array(hash)]\n    .map(byte => byte.toString(16).padStart(2, \"0\"))\n    .join(\"\");\n  console.log(hex);\n}\ncreateDigest().catch(console.error);","exercise":"digest یک فایل آزمایشی را محاسبه و تفاوت آن را با password hashing شرح بده.","status":"published","sort_order":34,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-35","course_id":"javascript-advanced","title":"Intl برای برنامه چندزبانه","slug":"javascript-advanced-35","summary":"Intl قالب‌بندی عدد، ارز، تاریخ و مرتب‌سازی وابسته به locale را انجام می‌دهد.","content_html":"<h3>هدف درس</h3><p>داده خام را از قالب نمایشی جدا نگه دار.</p><h3>نمونه و بررسی</h3><p>locale و timezone را صریح انتخاب کن.</p><pre><code>const money=new Intl.NumberFormat('fa-IR',{style:'currency',currency:'AFN'}); const sort=new Intl.Collator('fa',{numeric:true}); console.log(money.format(2450),['درس 10','درس 2'].sort(sort.compare));</code></pre><h3>تمرین عملی</h3><p>قیمت را با AFN و فهرست درس‌ها را با مرتب‌سازی عددی فارسی نمایش بده.</p><h3>نکته فنی</h3><p>خروجی ممکن است به داده‌های ICU محیط وابسته باشد.</p><h3>معیار موفقیت</h3><p>نمایش خوانا باشد و داده خام عددی بماند.</p>","starter_code":"const money=new Intl.NumberFormat('fa-IR',{style:'currency',currency:'AFN'}); const sort=new Intl.Collator('fa',{numeric:true}); console.log(money.format(2450),['درس 10','درس 2'].sort(sort.compare));","exercise":"قیمت را با AFN و فهرست درس‌ها را با مرتب‌سازی عددی فارسی نمایش بده.","status":"published","sort_order":35,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-36","course_id":"javascript-advanced","title":"پروژه نهایی: موتور همگام‌سازی آفلاین","slug":"javascript-advanced-36","summary":"پروژه ترکیبی IndexedDB، Service Worker، Cache، BroadcastChannel و مدیریت تعارض نسخه است.","content_html":"<h3>هدف درس</h3><p>APIهای پیشرفته را در معماری قابل آزمون ترکیب کن.</p><h3>نمونه و بررسی</h3><p>ذخیره محلی، صف ارسال و حل تعارض را جدا طراحی کن.</p><pre><code>const channel=new BroadcastChannel('academy-sync'); channel.postMessage({type:'progress',lessonId:'js-adv-36',revision:3}); channel.onmessage=e=&gt;console.log(e.data);</code></pre><h3>تمرین عملی</h3><p>پیشرفت آفلاین را ذخیره، هنگام اتصال صف را ارسال، تعارض را گزارش و تغییر را به زبانه دیگر اعلام کن.</p><h3>نکته فنی</h3><p>سرور منبع حقیقت است؛ درخواست‌ها باید idempotent و اعتبارسنجی شوند.</p><h3>معیار موفقیت</h3><p>قطع و وصل شبکه داده را از بین نبرد و تعارض پنهان نماند.</p>","starter_code":"const channel=new BroadcastChannel('academy-sync'); channel.postMessage({type:'progress',lessonId:'js-adv-36',revision:3}); channel.onmessage=e=>console.log(e.data);","exercise":"پیشرفت آفلاین را ذخیره، هنگام اتصال صف را ارسال، تعارض را گزارش و تغییر را به زبانه دیگر اعلام کن.","status":"published","sort_order":36,"estimated_minutes":120}]$lessons$::jsonb) as x(id text,course_id text,title text,slug text,summary text,content_html text,starter_code text,exercise text,status text,sort_order integer,estimated_minutes integer)
join (values
('html','html','beginner'),('html-intermediate','html','intermediate'),('html-advanced','html','advanced'),
('css','css','beginner'),('css-intermediate','css','intermediate'),('css-advanced','css','advanced'),
('javascript','javascript','beginner'),('javascript-intermediate','javascript','intermediate'),('javascript-advanced','javascript','advanced')
) as cp(course_id,language_id,level_id) on cp.course_id=x.course_id
join public.academy_courses c on c.language_id=cp.language_id and c.level_id=cp.level_id
on conflict(id) do update set title=excluded.title,slug=excluded.slug,summary=excluded.summary,content_html=excluded.content_html,starter_code=excluded.starter_code,exercise=excluded.exercise,status='published',sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,archived_at=null,updated_at=now();
commit;
